        rom[494] = {17'h1e077, 28'had2c804, 36'hf3ac958e3};
        rom[495] = {17'h1e11e, 28'had688f2, 36'hf459e0161};
        rom[496] = {17'h1e1c5, 28'hada4b2d, 36'hf50766b74};
        rom[497] = {17'h1e26c, 28'hade0eb6, 36'hf5b529869};
        rom[498] = {17'h1e313, 28'hae1d38d, 36'hf6632898e};
        rom[499] = {17'h1e3ba, 28'hae599b3, 36'hf71164032};
        rom[500] = {17'h1e462, 28'hae96128, 36'hf7bfdbda2};
        rom[501] = {17'h1e50a, 28'haed29ec, 36'hf86e90330};
        rom[502] = {17'h1e5b2, 28'haf0f401, 36'hf91d8122a};
        rom[503] = {17'h1e65b, 28'haf4bf65, 36'hf9ccaebe1};
        rom[504] = {17'h1e704, 28'haf88c1b, 36'hfa7c191a4};
        rom[505] = {17'h1e7ac, 28'hafc5a22, 36'hfb2bc04c6};
        rom[506] = {17'h1e856, 28'hb00297b, 36'hfbdba4699};
        rom[507] = {17'h1e8ff, 28'hb03fa26, 36'hfc8bc586d};
        rom[508] = {17'h1e9a9, 28'hb07cc24, 36'hfd3c23b95};
        rom[509] = {17'h1ea52, 28'hb0b9f75, 36'hfdecbf165};
        rom[510] = {17'h1eafc, 28'hb0f741a, 36'hfe9d97b30};
        rom[511] = {17'h1eba7, 28'hb134a12, 36'hff4eada49};
    end
    reg [WROM-1:0] rom_q;
    reg [RW-1:0]   w_r;
    reg            v_r;
    always @(posedge clk) begin
        if (rst) v_r <= 1'b0;
        else     v_r <= in_valid;
        rom_q <= rom[f[RW+K-1 -: K]];
        w_r   <= f[RW-1:0];
    end
    wire [W0-1:0] c0 = {1'b1, rom_q[W0-2:0]};
    wire [W1-1:0] c1 = rom_q[36 +: W1];
    wire [W2-1:0] c2 = rom_q[64 +: W2];

    // c0 + c1*w, the wide product, held if the chain takes longer.
    wire v_p;
    wire [W1+T1-1:0] p1;
    _zkf_pmul #(
        .WA(W1), .WB(T1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT)
    ) u_p1 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c1), .b(w_r[RW-1 -: T1]),
        .out_valid(v_p), .sb_out(), .p(p1)
    );
    wire [W0-1:0] c0_d;
    zkf_pipe #(.W(W0), .N(NK)) u_c0 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c0), .out_valid(), .out(c0_d)
    );
    wire [W1-1:0] p1_d;
    zkf_pipe #(.W(W1), .N(NK - 1 - STAGE_PRODUCT)) u_p1_d (
        .clk(clk), .rst(rst), .in_valid(v_p), .in(p1[W1+T1-1:T1]), .out_valid(out_valid), .out(p1_d)
    );

    wire [TS-1:0] ws = w_r[RW-1 -: TS];
    wire v_s;  // the valid of the square
    wire [W2-1:0] c2_s;
    zkf_pipe #(.W(W2), .N(STAGE_PRODUCT_SQUARE)) u_c2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c2), .out_valid(), .out(c2_s)
    );
    // chain = c2 * w**2, registered as the bits the last sum takes.
    wire [TS+TS-1:0] sq;
    _zkf_pmul #(
        .WA(TS), .WB(TS), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(SQP), .STAGE_OUTPUT(SQO)
    ) u_sq (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(ws), .b(ws),
        .out_valid(v_s), .sb_out(), .p(sq)
    );
    wire [W2+Q0-1:0] p2;
    _zkf_pmul #(
        .WA(W2), .WB(Q0), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p2 (
        .clk(clk), .rst(rst), .in_valid(v_s), .sb_in(1'b0), .a(c2_s), .b(sq[2*TS-1 -: Q0]),
        .out_valid(), .sb_out(), .p(p2)
    );
    wire [W2-1:0] p2_d;
    zkf_pipe #(.W(W2), .N(NK - NL)) u_p2_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(p2[W2+Q0-1:Q0]), .out_valid(), .out(p2_d)
    );
    // The argument bits below the wide product's operand times the top of c1: the rest of c1*w, at its
    // depth. It joins the chain in that register.
    localparam integer NPL = (STAGE_PRODUCT > 2) ? 2 : STAGE_PRODUCT;  // what a product this narrow admits
    wire [W1-SC+TC-1:0] pl;
    _zkf_pmul #(
        .WA(W1-SC), .WB(TC), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(NPL), .STAGE_OUTPUT(0)
    ) u_pl (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c1[W1-1:SC]), .b(w_r[TC-1:0]),
        .out_valid(), .sb_out(), .p(pl)
    );
    wire [9:0] pl_d;
    zkf_pipe #(.W(10), .N(NK - 1 - NPL)) u_pl_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(pl[W1-SC+TC-1 : RW-SC]), .out_valid(), .out(pl_d)
    );
    reg  [17:0] chain;
    always @(posedge clk) chain <= p2_d + pl_d;
    assign s = c0_d + p1_d + chain;
endmodule

